<script setup lang="ts">
/**
 * The create/edit screen (`design/archetypes/form-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/form-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, useTemplateRef } from 'vue'

import { useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/archetypes/form-page.module.css'
import Inline from '../layout/Inline.vue'
import PageHeader from '../structure/PageHeader.vue'

export interface FormPageProps {
  description?: string
  title: string
}

defineOptions({ name: 'FormPage', inheritAttrs: false })

defineProps<FormPageProps>()
const emit = defineEmits<{ submit: [] }>()
defineSlots<{
  actions: (props: Record<string, never>) => unknown
  default: (props: Record<string, never>) => unknown
  leadingAction?: (props: Record<string, never>) => unknown
}>()
const listening = useListening()
const form = useTemplateRef<HTMLElement>('form')
const submit = computed(() => (event: Event) => {
  event.preventDefault()
  const invalid = form.value?.querySelector<HTMLElement>('[aria-invalid="true"]')
  if (invalid) {
    invalid.focus()
    return
  }
  emit('submit')
})
</script>

<template>
  <div :class="styles.page" data-member="form-page">
    <PageHeader :title="title" :description="description" />
    <!-- form -->
    <form
      v-if="listening.submit"
      ref="form"
      :class="styles.form"
      :novalidate="true"
      @submit="submit($event)"
    >
      <slot />
      <!-- actions -->
      <div :class="styles.actions">
        <!-- split -->
        <div v-if="$slots.leadingAction" :class="styles.split">
          <slot name="leadingAction" />
          <!-- trailing -->
          <div :class="styles.trailing">
            <Inline :gap="3" justify="end" :wrap="true">
              <slot name="actions" />
            </Inline>
          </div>
        </div>
        <Inline v-else :gap="3" justify="end" :wrap="true">
          <slot name="actions" />
        </Inline>
      </div>
    </form>
    <template v-else>
      <slot />
      <!-- actions -->
      <div :class="styles.actions">
        <!-- split -->
        <div v-if="$slots.leadingAction" :class="styles.split">
          <slot name="leadingAction" />
          <!-- trailing -->
          <div :class="styles.trailing">
            <Inline :gap="3" justify="end" :wrap="true">
              <slot name="actions" />
            </Inline>
          </div>
        </div>
        <Inline v-else :gap="3" justify="end" :wrap="true">
          <slot name="actions" />
        </Inline>
      </div>
    </template>
  </div>
</template>
